import React, { useState, useEffect } from 'react';
import { useHistory } from 'react-router-dom';

function View() {
  const history = useHistory();
  const [post, setPost] = useState(null);
  const [showPhone, setShowPhone] = useState(false);

  useEffect(() => {
    const savedPost = localStorage.getItem('selectedPost');
    if (savedPost) {
      try {
        setPost(JSON.parse(savedPost));
      } catch (error) {
        console.error('Error parsing selected post:', error);
      }
    }
  }, []);

  if (!post) {
    return (
      <div style={{ textAlign: 'center', padding: '60px 20px' }}>
        <h3 style={{ color: '#002f34' }}>No product selected</h3>
        <button
          onClick={() => history.push('/')}
          style={{
            padding: '10px 20px',
            backgroundColor: '#002f34',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            fontWeight: 'bold',
            marginTop: '10px'
          }}
        >
          Back to Home
        </button>
      </div>
    );
  }

  const imgSrc =
    post.imageUrl ||
    post.image ||
    post.url ||
    post.photo ||
    post.img ||
    (Array.isArray(post.images) && post.images[0]) ||
    "";

  const formatDate = (dateString) => {
    if (!dateString) return "Recently listed";
    return new Date(dateString).toLocaleDateString('en-IN', {
      day: '2-digit',
      month: 'short',
      year: 'numeric'
    });
  };

  const handleWhatsAppChat = () => {
    if (!post.sellerPhone) {
      alert("Seller did not provide a WhatsApp number for this listing.");
      return;
    }
    const cleanPhone = post.sellerPhone.replace(/\D/g, '');
    const phoneWithCountry = cleanPhone.length === 10 ? `91${cleanPhone}` : cleanPhone;
    const message = `Hi ${post.sellerName || 'there'}, I am interested in your listing "${post.title || post.name}" priced at ₹${post.price} on Thrift Shop.`;
    window.open(`https://wa.me/${phoneWithCountry}?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div style={{ maxWidth: '1100px', margin: '30px auto', padding: '0 20px' }}>
      <button
        onClick={() => history.push('/')}
        style={{
          marginBottom: '20px',
          padding: '8px 16px',
          backgroundColor: 'transparent',
          color: '#002f34',
          border: '1px solid #002f34',
          borderRadius: '4px',
          cursor: 'pointer',
          fontWeight: 'bold'
        }}
      >
        ← Back to Products
      </button>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '30px' }}>
        {/* Left Side: Product Image & Description */}
        <div style={{ flex: '1 1 550px' }}>
          <div
            style={{
              width: '100%',
              height: '420px',
              backgroundColor: '#000',
              borderRadius: '8px',
              overflow: 'hidden',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              border: '1px solid #ddd'
            }}
          >
            {imgSrc ? (
              <img
                src={imgSrc}
                alt={post.title || post.name}
                style={{ maxWidth: '100%', maxHeight: '100%', objectFit: 'contain' }}
              />
            ) : (
              <span style={{ color: '#ccc' }}>No Image Available</span>
            )}
          </div>

          <div
            style={{
              marginTop: '20px',
              padding: '20px',
              border: '1px solid #ddd',
              borderRadius: '8px',
              backgroundColor: '#fff'
            }}
          >
            <h3 style={{ margin: '0 0 10px 0', color: '#002f34' }}>Description</h3>
            <p style={{ margin: 0, color: '#444', lineHeight: '1.6', whiteSpace: 'pre-line' }}>
              {post.description || "No additional description provided by the seller."}
            </p>
          </div>
        </div>

        {/* Right Side: Price, Location & Seller Info */}
        <div style={{ flex: '1 1 320px', display: 'flex', flexDirection: 'column', gap: '20px' }}>
          {/* Price & Title Card */}
          <div style={{ padding: '20px', border: '1px solid #ddd', borderRadius: '8px', backgroundColor: '#fff' }}>
            <h1 style={{ margin: '0 0 10px 0', color: '#002f34', fontSize: '30px' }}>
              ₹ {Number(post.price).toLocaleString('en-IN')}
            </h1>
            <h3 style={{ margin: '0 0 10px 0', color: '#333', fontWeight: '500' }}>
              {post.title || post.name}
            </h3>

            {post.category && (
              <span
                style={{
                  display: 'inline-block',
                  fontSize: '12px',
                  backgroundColor: '#eef3f4',
                  color: '#002f34',
                  padding: '4px 10px',
                  borderRadius: '12px',
                  fontWeight: 'bold',
                  marginBottom: '12px'
                }}
              >
                {post.category}
              </span>
            )}

            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '13px', color: '#666', borderTop: '1px solid #eee', paddingTop: '12px', marginTop: '8px' }}>
              <span>📍 {post.location || 'India'}</span>
              <span>Listed on {formatDate(post.createdAt)}</span>
            </div>
          </div>

          {/* Seller Details Card */}
          <div style={{ padding: '20px', border: '1px solid #ddd', borderRadius: '8px', backgroundColor: '#fff' }}>
            <h3 style={{ margin: '0 0 12px 0', color: '#002f34' }}>Seller Details</h3>
            <p style={{ margin: '0 0 6px 0', fontSize: '16px', fontWeight: 'bold', color: '#222' }}>
              👤 {post.sellerName || "Thrift Shop Seller"}
            </p>
            <p style={{ margin: '0 0 16px 0', fontSize: '13px', color: '#666' }}>
              Verified Community Member
            </p>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              <button
                onClick={() => setShowPhone(!showPhone)}
                style={{
                  width: '100%',
                  padding: '12px',
                  backgroundColor: '#002f34',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  fontWeight: 'bold',
                  fontSize: '15px',
                  cursor: 'pointer'
                }}
              >
                {showPhone
                  ? `📞 ${post.sellerPhone || "Number not provided"}`
                  : "Show Phone Number"}
              </button>

              {post.sellerPhone && (
                <button
                  onClick={handleWhatsAppChat}
                  style={{
                    width: '100%',
                    padding: '12px',
                    backgroundColor: '#25D366',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    fontWeight: 'bold',
                    fontSize: '15px',
                    cursor: 'pointer'
                  }}
                >
                  💬 Chat on WhatsApp
                </button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default View;
